/**
 * Live model discovery from `devin models list`.
 *
 * # Why the baked catalogue is not enough
 *
 * `src/models.ts` is generated by `scripts/refresh-models.mjs` on whichever
 * machine last ran it, so it reflects *that* host's CLI version and — more
 * importantly — *that* account's subscription. The model list is not a
 * constant: what `devin models list` prints depends on the plan the logged-in
 * account is on, and subscriptions change without a CLI update. Shipping the
 * snapshot as the only source meant every user saw someone else's catalogue.
 *
 * The fix is the same one the built-in adapters use (`opencode models`,
 * Anthropic's `/v1/models`): ask the CLI on the host the agent runs on, cache
 * briefly so the config form stays snappy, and keep the generated catalogue
 * purely as the fallback for when the probe cannot run (binary missing,
 * logged out, CLI too old).
 */

import { execFile } from "node:child_process";
import { promisify } from "node:util";

import type { AdapterModel } from "@paperclipai/adapter-utils";

import { DEFAULT_COMMAND } from "../config.js";
import { DEVIN_MODELS, type DevinModel } from "../models.js";
import { resolveCommandPath } from "./resolve-command.js";

const execFileAsync = promisify(execFile);

const PROBE_TIMEOUT_MS = 15_000;
/** How long a successful catalogue is served before re-probing. */
const MODELS_CACHE_TTL_MS = 60_000;
/**
 * How long a failed probe is remembered. Short, so that a `devin auth login`
 * in another window shows up almost immediately, but nonzero so a missing
 * binary does not get spawned on every schema/models request.
 */
const MODELS_FAILURE_TTL_MS = 15_000;

/** One `devin` invocation; injectable so tests never spawn a real process. */
export type ModelsListRunner = (
  command: string,
  args: string[],
) => Promise<{ ok: boolean; stdout: string; stderr: string }>;

const defaultRunner: ModelsListRunner = async (command, args) => {
  try {
    const { stdout, stderr } = await execFileAsync(command, args, {
      timeout: PROBE_TIMEOUT_MS,
      encoding: "utf8",
    });
    return { ok: true, stdout, stderr };
  } catch (error) {
    const err = error as { stdout?: string; stderr?: string; message?: string };
    return {
      ok: false,
      stdout: err.stdout ?? "",
      // `||` not `??`: execFile reports a spawn failure (ENOENT, EACCES) with
      // an empty stderr and the real reason in `message`.
      stderr: err.stderr || err.message || String(error),
    };
  }
};

/**
 * Which binary to ask. `listModels`/`getConfigSchema` receive no agent config,
 * so a per-agent `command` cannot reach here; the env override covers hosts
 * where `devin` is not on the server PATH (same escape hatch as
 * `PAPERCLIP_OPENCODE_COMMAND` in opencode-local).
 */
function discoveryCommand(): string {
  const override = process.env.PAPERCLIP_DEVIN_COMMAND?.trim();
  return resolveCommandPath(override || DEFAULT_COMMAND);
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

interface DevinModelsJsonFamily {
  family_label?: unknown;
  family_uid?: unknown;
  slug?: unknown;
  variants?: unknown;
}

interface DevinModelsJsonVariant {
  model_uid?: unknown;
  label?: unknown;
}

function dedupeModels(models: DevinModel[]): DevinModel[] {
  const seen = new Set<string>();
  const deduped: DevinModel[] = [];
  for (const model of models) {
    const id = model.id.trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    deduped.push({ ...model, id, label: model.label.trim() || id });
  }
  return deduped;
}

/** Parses `--format json` output: `{ families: [{ family_label, variants: [{ model_uid, label }] }] }`. */
export function parseDevinModelsJson(stdout: string): DevinModel[] {
  const payload = JSON.parse(stdout) as { families?: unknown };
  const families = Array.isArray(payload.families) ? payload.families : [];

  const models: DevinModel[] = [];
  for (const rawFamily of families) {
    if (typeof rawFamily !== "object" || rawFamily === null) continue;
    const family = rawFamily as DevinModelsJsonFamily;
    const familyLabel =
      (typeof family.family_label === "string" && family.family_label.trim()) ||
      (typeof family.family_uid === "string" && family.family_uid.trim()) ||
      (typeof family.slug === "string" && family.slug.trim()) ||
      "";
    const variants = Array.isArray(family.variants) ? family.variants : [];

    for (const rawVariant of variants) {
      if (typeof rawVariant !== "object" || rawVariant === null) continue;
      const variant = rawVariant as DevinModelsJsonVariant;
      if (typeof variant.model_uid !== "string" || !variant.model_uid.trim()) continue;
      models.push({
        id: variant.model_uid,
        label:
          typeof variant.label === "string" && variant.label.trim()
            ? variant.label
            : variant.model_uid,
        family: familyLabel,
      });
    }
  }
  return dedupeModels(models);
}

// "Claude Opus 5 (claude-opus-5)" starts a family;
// "  claude-opus-5-low   Claude Opus 5 Low  [1M context, ...]" is a model.
const TEXT_FAMILY = /^(\S.*?) \(([a-z0-9._-]+)\)$/;
const TEXT_MODEL = /^ {2}([a-z0-9._-]+)\s{2,}(.+?)(?:\s*\[.+\])?$/;

/**
 * Parses the default text output, for CLIs old enough to lack `--format json`.
 * Same grammar as `scripts/refresh-models.mjs` — keep them in sync.
 */
export function parseDevinModelsText(stdout: string): DevinModel[] {
  const models: DevinModel[] = [];
  let family = "";

  for (const line of stdout.split("\n")) {
    const trimmedEnd = line.replace(/\s+$/, "");

    const familyMatch = TEXT_FAMILY.exec(trimmedEnd);
    if (familyMatch?.[1]) {
      family = familyMatch[1];
      continue;
    }

    if (trimmedEnd.trim().startsWith("aliases:")) continue;

    const modelMatch = TEXT_MODEL.exec(trimmedEnd);
    if (modelMatch?.[1] && modelMatch[2] && family) {
      models.push({ id: modelMatch[1], label: modelMatch[2].trim(), family });
    }
  }
  return dedupeModels(models);
}

// ---------------------------------------------------------------------------
// Discovery
// ---------------------------------------------------------------------------

/**
 * Asks the CLI for the catalogue. Returns the parsed list — possibly empty if
 * the subscription genuinely exposes none — and throws only when the CLI
 * itself could not produce a catalogue.
 */
export async function discoverDevinModels(options: {
  command?: string;
  run?: ModelsListRunner;
} = {}): Promise<DevinModel[]> {
  const command = options.command ?? discoveryCommand();
  const run = options.run ?? defaultRunner;

  const json = await run(command, ["models", "list", "--format", "json"]);
  if (json.ok) {
    try {
      return parseDevinModelsJson(json.stdout);
    } catch {
      // Output was not JSON after all; fall through to the text grammar.
    }
  }

  const text = await run(command, ["models", "list"]);
  if (text.ok) {
    const models = parseDevinModelsText(text.stdout);
    if (models.length > 0) return models;
  }

  const detail = (text.stderr || json.stderr).trim().split("\n")[0] ?? "";
  throw new Error(
    detail
      ? `\`devin models list\` failed: ${detail}`
      : "`devin models list` produced no catalogue.",
  );
}

interface CatalogueCacheEntry {
  expiresAt: number;
  models: DevinModel[];
}

const catalogueCache = new Map<string, CatalogueCacheEntry>();
const inflight = new Map<string, Promise<DevinModel[]>>();

function fallbackCatalogue(): DevinModel[] {
  return dedupeModels(DEVIN_MODELS);
}

/**
 * The model catalogue the UI should show: the CLI's answer while it works,
 * the generated snapshot otherwise.
 *
 * A failed probe is cached for `MODELS_FAILURE_TTL_MS` rather than not cached
 * at all — both `/models` and `/config-schema` hit this, and a missing or
 * logged-out binary would otherwise be spawned on every request.
 */
export async function loadDevinModelCatalogue(options: {
  command?: string;
  run?: ModelsListRunner;
  forceRefresh?: boolean;
} = {}): Promise<DevinModel[]> {
  const command = options.command ?? discoveryCommand();
  const now = Date.now();

  const cached = catalogueCache.get(command);
  if (options.forceRefresh !== true && cached && cached.expiresAt > now) {
    return cached.models;
  }

  const pending = inflight.get(command);
  if (options.forceRefresh !== true && pending) return pending;

  const probe = (async (): Promise<DevinModel[]> => {
    try {
      const models = await discoverDevinModels({ command, run: options.run });
      const catalogue = models.length > 0 ? models : fallbackCatalogue();
      catalogueCache.set(command, {
        expiresAt: Date.now() + MODELS_CACHE_TTL_MS,
        models: catalogue,
      });
      return catalogue;
    } catch (error) {
      console.warn(
        `[devin_local] model discovery failed, serving the packaged catalogue: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
      const catalogue = fallbackCatalogue();
      catalogueCache.set(command, {
        expiresAt: Date.now() + MODELS_FAILURE_TTL_MS,
        models: catalogue,
      });
      return catalogue;
    } finally {
      inflight.delete(command);
    }
  })();

  inflight.set(command, probe);
  return probe;
}

/** Registry hook: cached discovery for `GET .../adapters/:type/models`. */
export async function listDevinModels(): Promise<AdapterModel[]> {
  const catalogue = await loadDevinModelCatalogue();
  return catalogue.map((model) => ({ id: model.id, label: model.label }));
}

/** Registry hook: bypasses the cache for `.../models?refresh=1`. */
export async function refreshDevinModels(): Promise<AdapterModel[]> {
  const catalogue = await loadDevinModelCatalogue({ forceRefresh: true });
  return catalogue.map((model) => ({ id: model.id, label: model.label }));
}

export function resetDevinModelsCacheForTests(): void {
  catalogueCache.clear();
  inflight.clear();
}
